import{_ as a,o as i,c as s,a6 as o}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Ciclo de vida, propriedade e limpeza","description":"","frontmatter":{"title":"Ciclo de vida, propriedade e limpeza","docId":"developer.lifecycle","translationKey":"developer.lifecycle","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"3e866271067cf2c4d374aaccd9a6cdf6babf981df4deeff5313947cbf39b5cc7","translationRevision":"29db543b3e2cf2d59d3df2ae69350f63b9326241e3c816ec498afc51f3796e30","order":50},"headers":[],"relativePath":"pt/developer/lifecycle.md","filePath":"pt/developer/lifecycle.md","lastUpdated":1794611623000}'),t={name:"pt/developer/lifecycle.md"};function r(n,e,l,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="lifecycle-ownership-and-cleanup" tabindex="-1">Ciclo de vida, propriedade e limpeza <a class="header-anchor" href="#lifecycle-ownership-and-cleanup" aria-label="Permalink to &quot;Ciclo de vida, propriedade e limpeza {#lifecycle-ownership-and-cleanup}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Faça montagem, reconexão e encerramento liberarem os recursos pelos quais são responsáveis. Conheça a <a href="./architecture.html">arquitetura</a> e use um <code>TIKTOOLS_HOME</code> isolado para experimentos nativos de ciclo de vida. Cancelar uma assinatura do frontend e encerrar o host resolvem problemas de propriedade diferentes.</p><h2 id="follow-the-desktop-lifetime" tabindex="-1">Siga o tempo de vida do desktop <a class="header-anchor" href="#follow-the-desktop-lifetime" aria-label="Permalink to &quot;Siga o tempo de vida do desktop {#follow-the-desktop-lifetime}&quot;">​</a></h2><p><code>crates/tiktools-desktop/src/app.rs</code> implementa o manipulador de aplicativo do Winit. A criação de janela e WebView ocorre na thread do laço de eventos. A janela começa oculta e aparece depois que Vue envia <code>frontend-ready</code>. Fechar oculta a janela quando há bandeja; sem bandeja, inicia o encerramento. Sair pede ao núcleo para parar seus serviços antes de encerrar o laço de eventos.</p><p><code>crates/tiktools-core/src/shutdown.rs</code> fecha cedo a admissão de inicialização de plugins, para coordenação em segundo plano e monitoramento, desconecta a LIVE e drena o trabalho sob sua responsabilidade. Chamadores repetidos de encerramento aguardam a mesma conclusão. Descartar um future não pode parar código nativo arbitrário nem desfazer um efeito externo.</p><h2 id="own-frontend-resources-explicitly" tabindex="-1">Gerencie recursos do frontend explicitamente <a class="header-anchor" href="#own-frontend-resources-explicitly" aria-label="Permalink to &quot;Gerencie recursos do frontend explicitamente {#own-frontend-resources-explicitly}&quot;">​</a></h2><p>Use o padrão já seguido por <code>use-app-runtime.ts</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { onUnmounted } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vue&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { useControlClient } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@/shared/api/use-control-client.ts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useControlClient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> stop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> control.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onTopic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;points.changed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Atualize aqui a apresentação confirmada do store responsável.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onUnmounted</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(stop);</span></span></code></pre></div><p>O corpo do callback pertence à entidade responsável pela visualização. Um recurso deve descartar suas assinaturas, temporizadores, quadros de animação e escopos de requisição, enquanto a inicialização do aplicativo é responsável por conectar e desconectar o transporte compartilhado. Alterações de modelo de widget devem descartar o controlador anterior em vez de deixar seus temporizadores de alerta executando.</p><h2 id="expected-result-and-verification" tabindex="-1">Resultado esperado e verificação <a class="header-anchor" href="#expected-result-and-verification" aria-label="Permalink to &quot;Resultado esperado e verificação {#expected-result-and-verification}&quot;">​</a></h2><p>Sair de uma página e voltar não multiplica callbacks. Quando oculta, a apresentação interrompe renderizações desnecessárias sem pausar a contabilização autoritativa. Reconectar informa lacunas e recarrega instantâneos; não reproduz efeitos de negócio. Execute <code>bun scripts/task.ts test web cloud-lifecycle</code> e <code>bun scripts/task.ts test web request-scope</code> para exemplos específicos.</p><h2 id="recovery-and-limits" tabindex="-1">Recuperação e limites <a class="header-anchor" href="#recovery-and-limits" aria-label="Permalink to &quot;Recuperação e limites {#recovery-and-limits}&quot;">​</a></h2><p>Uma inicialização QuickJS que excedeu o tempo limite pode permanecer incerta; o gerenciador mantém a identidade do worker e bloqueia a substituição em vez de fingir que a parada funcionou. Alguns caminhos síncronos de controle do ciclo de vida de plugins ainda podem bloquear o chamador. Trate-os como limites de implementação, especialmente durante encaminhamento ao atualizador. Pare corretamente o host proprietário em vez de excluir seu bloqueio ativo. O <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/shutdown.rs" target="_blank" rel="noreferrer">código de encerramento</a> e os testes de execução são evidências mais fortes que um diagrama histórico de ciclo de vida.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>O encerramento para a admissão LIVE e drena a entrada, cancela observadores/desconecta e para o polling dos plugins. Esvazia Analytics, resolve gravações de pontos (30 s), faz checkpoint SQLite (5 s) e conclui o encerramento nativo. Timeout de polling, falha analítica, pontos pendentes ou checkpoint falho tornam a atualização insegura. <code>AppCore::update_shutdown_safe()</code> exige conclusão e sinalizador seguro; concluir não basta. O atualizador usa esse resultado nativo, sem controle do usuário que certifique trabalho incerto. Preserve logs/recuperação pendente e resolva a incerteza antes de trocar binários.</p>`,16)])])}const k=a(t,[["render",r]]);export{u as __pageData,k as default};
